    public Task<Dictionary<string, List<string>>> ValidatePatientAsync(AppointmentModel model)
    {
        var errors = new Dictionary<string, List<string>>();

        // Reject "taken@example.com" for outstanding balance
        if (string.Equals(model.Email, "taken@example.com", StringComparison.OrdinalIgnoreCase))
        {
            errors[nameof(model.Email)] = ["Account has outstanding balance"];
        }

        // Reject "None" insurance with Dr. Smith (doesn't accept self-pay)
        if (model.InsuranceProvider == "None")
        {
            var doctor = Doctors.FirstOrDefault(d => d.Name == model.Doctor);
            if (doctor is not null && !doctor.AcceptsSelfPay)
            {
                errors[nameof(model.Doctor)] = ["Selected doctor does not accept self-pay patients"];
            }
        }

        // Reject "10:00 AM" as already taken
        if (model.TimeSlot == "10:00 AM")
        {
            errors[nameof(model.TimeSlot)] = ["This slot is no longer available"];
        }

        return Task.FromResult(errors);
    }

    public Task<bool> BookAppointmentAsync(AppointmentModel model)
    {
        // Stub: always succeeds
        return Task.FromResult(true);
    }
