@page "/book-appointment"
@rendermode InteractiveServer
@using sv_cff06fff6d6d4103bb2a88fceb137ca7.Models
@using sv_cff06fff6d6d4103bb2a88fceb137ca7.Services
@inject AppointmentService AppointmentSvc

<PageTitle>Book Appointment</PageTitle>

<h1>Book an Appointment</h1>

@if (isBooked)
{
    <div class="alert alert-success">
        <h4>Appointment Confirmed!</h4>
        <p>Thank you, <strong>@Model.PatientName</strong>. Your appointment with <strong>@Model.Doctor</strong> on @Model.AppointmentDate?.ToString("MMMM d, yyyy") at @Model.TimeSlot has been booked.</p>
    </div>
}
else
{
    <EditForm EditContext="editContext" OnSubmit="HandleSubmit" FormName="book-appointment">
        <DataAnnotationsValidator />
        <CustomValidator @ref="customValidator" />

        <fieldset>
            <legend>Step 1 — Patient Information</legend>

            <div class="mb-3">
                <label class="form-label">Patient Name</label>
                <InputText class="form-control" @bind-Value="Model.PatientName" />
                <ValidationMessage For="() => Model.PatientName" />
            </div>

            <div class="mb-3">
                <label class="form-label">Email</label>
                <InputText class="form-control" @bind-Value="Model.Email" />
                <ValidationMessage For="() => Model.Email" />
            </div>

            <div class="mb-3">
                <label class="form-label">Phone</label>
                <InputText class="form-control" @bind-Value="Model.Phone" />
                <ValidationMessage For="() => Model.Phone" />
            </div>

            <div class="mb-3">
                <label class="form-label">Insurance Provider</label>
                <InputSelect class="form-control" @bind-Value="Model.InsuranceProvider">
                    <option value="">-- Select --</option>
                    <option value="Aetna">Aetna</option>
                    <option value="BlueCross">BlueCross</option>
                    <option value="Cigna">Cigna</option>
                    <option value="UnitedHealth">UnitedHealth</option>
                    <option value="None">None</option>
                </InputSelect>
                <ValidationMessage For="() => Model.InsuranceProvider" />
            </div>

            @if (!showStep2)
            {
                <button type="button" class="btn btn-primary" @onclick="ProceedToStep2">
                    Next &rarr;
                </button>
            }
        </fieldset>

        @if (showStep2)
        {
            <fieldset class="mt-4">
                <legend>Step 2 — Appointment Details</legend>

                <div class="mb-3">
                    <label class="form-label">Preferred Doctor</label>
                    <InputSelect class="form-control" @bind-Value="Model.Doctor">
                        <option value="">-- Select --</option>
                        @foreach (var doc in doctors)
                        {
                            <option value="@doc.Name">@doc.Name</option>
                        }
                    </InputSelect>
                    <ValidationMessage For="() => Model.Doctor" />
                </div>

                <div class="mb-3">
                    <label class="form-label">Date</label>
                    <InputDate class="form-control" @bind-Value="Model.AppointmentDate" @bind:after="OnDateChanged" />
                    <ValidationMessage For="() => Model.AppointmentDate" />
                    @if (Model.AppointmentDate.HasValue && Model.AppointmentDate.Value <= DateOnly.FromDateTime(DateTime.Today))
                    {
                        <div class="text-danger">Date must be in the future.</div>
                    }
                </div>

                <div class="mb-3">
                    <label class="form-label">Time Slot</label>
                    <InputSelect class="form-control" @bind-Value="Model.TimeSlot" disabled="@(availableSlots.Count == 0)">
                        <option value="">-- Select --</option>
                        @foreach (var slot in availableSlots)
                        {
                            <option value="@slot">@slot</option>
                        }
                    </InputSelect>
                    <ValidationMessage For="() => Model.TimeSlot" />
                    @if (availableSlots.Count == 0 && !string.IsNullOrEmpty(Model.Doctor) && Model.AppointmentDate.HasValue)
                    {
                        <div class="text-muted">Loading slots...</div>
                    }
                </div>

                <div class="mb-3">
                    <label class="form-label">Reason for Visit</label>
                    <InputTextArea class="form-control" @bind-Value="Model.ReasonForVisit" rows="4" />
                    <ValidationMessage For="() => Model.ReasonForVisit" />
                    <small class="text-muted">@((Model.ReasonForVisit?.Length ?? 0))/500 characters</small>
                </div>

                <div class="d-flex gap-2">
                    <button type="button" class="btn btn-secondary" @onclick="BackToStep1">&larr; Back</button>
                    <button type="button" class="btn btn-info" @onclick="CheckAvailability" disabled="@isChecking">
                        @(isChecking ? "Checking..." : "Check Availability")
                    </button>
                    <button type="submit" class="btn btn-success" disabled="@(!availabilityChecked || isSubmitting)">
                        @(isSubmitting ? "Booking..." : "Book Appointment")
                    </button>
                </div>
            </fieldset>
        }
    </EditForm>
}

@code {
    private AppointmentModel Model = new();
    private EditContext editContext = default!;
    private CustomValidator? customValidator;

    private List<DoctorInfo> doctors = [];
    private List<string> availableSlots = [];

    private bool showStep2;
    private bool isChecking;
    private bool isSubmitting;
    private bool isBooked;
    private bool availabilityChecked;

    // Fields that belong to step 1 for partial validation
    private static readonly string[] Step1Fields =
        [nameof(AppointmentModel.PatientName), nameof(AppointmentModel.Email),
         nameof(AppointmentModel.Phone), nameof(AppointmentModel.InsuranceProvider)];

    protected override async Task OnInitializedAsync()
    {
        editContext = new EditContext(Model);
        doctors = await AppointmentSvc.GetDoctorsAsync();
    }

    private void ProceedToStep2()
    {
        // Validate only step 1 fields
        var isStep1Valid = editContext.Validate();

        // Check if any step 1 field has errors
        if (Step1Fields.All(f => !editContext.GetValidationMessages(editContext.Field(f)).Any()))
        {
            showStep2 = true;
        }
    }

    private void BackToStep1()
    {
        showStep2 = false;
        availabilityChecked = false;
    }

    private async Task OnDateChanged()
    {
        availableSlots.Clear();
        Model.TimeSlot = null;
        availabilityChecked = false;

        if (!string.IsNullOrEmpty(Model.Doctor) && Model.AppointmentDate.HasValue
            && Model.AppointmentDate.Value > DateOnly.FromDateTime(DateTime.Today))
        {
            availableSlots = await AppointmentSvc.GetAvailableSlotsAsync(Model.Doctor, Model.AppointmentDate.Value);
        }
    }

    private async Task CheckAvailability()
    {
        customValidator?.ClearErrors();
        availabilityChecked = false;

        // Validate the full form via data annotations first
        if (!editContext.Validate())
            return;

        // Check future date
        if (Model.AppointmentDate.HasValue && Model.AppointmentDate.Value <= DateOnly.FromDateTime(DateTime.Today))
            return;

        isChecking = true;
        try
        {
            var errors = await AppointmentSvc.ValidatePatientAsync(Model);
            if (errors.Count > 0)
            {
                customValidator!.DisplayErrors(errors);
                return;
            }

            availabilityChecked = true;
        }
        finally
        {
            isChecking = false;
        }
    }

    private async Task HandleSubmit()
    {
        if (!availabilityChecked)
            return;

        customValidator?.ClearErrors();

        if (!editContext.Validate())
            return;

        if (Model.AppointmentDate.HasValue && Model.AppointmentDate.Value <= DateOnly.FromDateTime(DateTime.Today))
            return;

        isSubmitting = true;
        try
        {
            // Re-validate server-side before final booking
            var errors = await AppointmentSvc.ValidatePatientAsync(Model);
            if (errors.Count > 0)
            {
                customValidator!.DisplayErrors(errors);
                availabilityChecked = false;
                return;
            }

            await AppointmentSvc.BookAppointmentAsync(Model);
            isBooked = true;
        }
        finally
        {
            isSubmitting = false;
        }
    }
}

